'use client'

import { useState, useEffect, useRef, useCallback, type RefObject } from 'react'
import { motion, AnimatePresence, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { playHoverSound, playClickSound } from '@/lib/sound'
import { CircularProgress } from './circular-progress'

export interface TOCSection {
  id: string
  title: string
  level?: number
}

interface TableOfContentsProps {
  sections: TOCSection[]
  scrollOffset?: number
  showAfterScroll?: number
  scrollContainer?: RefObject<HTMLElement | null>
  className?: string
}

export function TableOfContents({
  sections,
  scrollOffset = 120,
  showAfterScroll = 300,
  scrollContainer,
  className,
}: TableOfContentsProps) {
  const [isExpanded, setIsExpanded] = useState(false)
  const [isVisible, setIsVisible] = useState(false)
  const [activeId, setActiveId] = useState<string>('')
  const [scrollProgress, setScrollProgress] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)
  const rafRef = useRef<number>(0)
  const prefersReduced = useReducedMotion()

  useEffect(() => {
    let ticking = false
    const el = scrollContainer?.current

    const getScrollTop = () => (el ? el.scrollTop : window.scrollY)
    const getScrollHeight = () =>
      el
        ? el.scrollHeight - el.clientHeight
        : document.documentElement.scrollHeight - window.innerHeight

    const handleScroll = () => {
      if (!ticking) {
        rafRef.current = requestAnimationFrame(() => {
          const scrollTop = getScrollTop()
          const height = getScrollHeight()
          const scrolled = height > 0 ? (scrollTop / height) * 100 : 0

          setScrollProgress(scrolled)
          setIsVisible(scrollTop > showAfterScroll)
          ticking = false
        })
        ticking = true
      }
    }

    const target = el || window
    target.addEventListener('scroll', handleScroll, { passive: true })
    handleScroll()

    return () => {
      target.removeEventListener('scroll', handleScroll)
      cancelAnimationFrame(rafRef.current)
    }
  }, [showAfterScroll, scrollContainer])

  useEffect(() => {
    const root = scrollContainer?.current ?? null
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)

        if (visible.length > 0) {
          setActiveId(visible[0].target.id)
        }
      },
      { root, rootMargin: '-10% 0% -60% 0%', threshold: 0 },
    )

    sections.forEach((section) => {
      const element = document.getElementById(section.id)
      if (element) observer.observe(element)
    })

    return () => observer.disconnect()
  }, [sections, scrollContainer])

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsExpanded(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const scrollToSection = useCallback(
    (id: string) => {
      playClickSound()
      const element = document.getElementById(id)
      if (!element) return

      const el = scrollContainer?.current
      if (el) {
        const containerTop = el.getBoundingClientRect().top
        const elementTop = element.getBoundingClientRect().top
        const scrollTop = el.scrollTop + (elementTop - containerTop) - scrollOffset
        el.scrollTo({ top: scrollTop, behavior: 'smooth' })
      } else {
        const elementPosition = element.getBoundingClientRect().top + window.scrollY
        window.scrollTo({ top: elementPosition - scrollOffset, behavior: 'smooth' })
      }
      setIsExpanded(false)
    },
    [scrollOffset, scrollContainer],
  )

  const activeSection = sections.find((s) => s.id === activeId) || sections[0]

  const entranceTransition = prefersReduced
    ? { duration: 0.01 }
    : { type: 'spring' as const, damping: 25, stiffness: 300 }

  const panelTransition = prefersReduced
    ? { duration: 0.01 }
    : { duration: 0.2, ease: 'easeOut' as const }

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          ref={containerRef}
          initial={{ opacity: 0, y: 40, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 40, scale: 0.95 }}
          transition={entranceTransition}
          className={cn('fixed bottom-8 inset-e-8 z-100 w-[calc(100%-2rem)] max-w-sm', className)}
        >
          <AnimatePresence>
            {isExpanded && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 10 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 10 }}
                transition={panelTransition}
                className="mb-3 w-full overflow-hidden rounded-md bg-(--color-surface) p-2"
              >
                <div className="no-scrollbar max-h-[50vh] space-y-0.5 overflow-y-auto py-1">
                  {sections.map((section) => {
                    const isActive = activeId === section.id
                    const level = section.level ?? 2
                    return (
                      <button
                        key={section.id}
                        onMouseEnter={() => playHoverSound()}
                        onClick={() => scrollToSection(section.id)}
                        className={cn(
                          'relative w-full rounded-md px-4 py-2.5 text-left text-sm transition-colors',
                          isActive
                            ? 'bg-(--color-fg)/10 text-(--color-fg)'
                            : 'text-(--color-muted) hover:bg-(--color-surface-2) hover:text-(--color-fg)',
                          level > 2 ? 'pl-8 text-[13px]' : 'pl-4 font-medium',
                        )}
                      >
                        {section.title}
                      </button>
                    )
                  })}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <button
            type="button"
            aria-expanded={isExpanded}
            aria-label={`Table of contents: ${activeSection?.title ?? ''}`}
            onMouseEnter={() => playHoverSound()}
            onClick={() => {
              playClickSound()
              setIsExpanded(!isExpanded)
            }}
            onKeyDown={(e) => {
              if (e.key === 'Escape' && isExpanded) {
                e.preventDefault()
                setIsExpanded(false)
              }
            }}
            className="group flex h-14 w-full items-center justify-between rounded-md border border-(--color-border) bg-(--color-surface) px-6 transition-transform active:scale-[0.98]"
          >
            <span className="truncate text-sm font-semibold text-(--color-fg)">
              {activeSection?.title}
            </span>

            <div className="flex items-center gap-3">
              <div className="h-4 w-px bg-(--color-border)" />
              <CircularProgress progress={scrollProgress} />
              <motion.div
                animate={{ rotate: isExpanded ? 180 : 0 }}
                transition={prefersReduced ? { duration: 0.01 } : { duration: 0.2 }}
                className="text-(--color-muted) group-hover:text-(--color-fg)"
              >
                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M5 15l7-7 7 7"
                  />
                </svg>
              </motion.div>
            </div>
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

'use client'

import { forwardRef, type ComponentPropsWithoutRef } from 'react'
import { cn } from '@/lib/utils'

interface CircularProgressProps extends ComponentPropsWithoutRef<'svg'> {
  progress: number
  size?: number
  strokeWidth?: number
  trackClassName?: string
  progressClassName?: string
  showValue?: boolean
  valueClassName?: string
}

const MIN_LABEL_SIZE = 32

export const CircularProgress = forwardRef<SVGSVGElement, CircularProgressProps>(
  function CircularProgress(
    {
      progress,
      size = 18,
      strokeWidth = 2,
      className,
      trackClassName,
      progressClassName,
      showValue = false,
      valueClassName,
      ...props
    },
    ref,
  ) {
    const radius = (size - strokeWidth) / 2
    const circumference = radius * 2 * Math.PI
    const safeProgress = Math.max(0, Math.min(100, progress))
    const offset = circumference - (safeProgress / 100) * circumference
    const showLabel = showValue && size >= MIN_LABEL_SIZE

    return (
      <svg
        ref={ref}
        width={size}
        height={size}
        className={cn('block -rotate-90 overflow-visible', className)}
        aria-valuenow={safeProgress}
        aria-valuemin={0}
        aria-valuemax={100}
        role="progressbar"
        {...props}
      >
        <circle
          className={cn('text-foreground/10', trackClassName)}
          strokeWidth={strokeWidth}
          stroke="currentColor"
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
        />
        <circle
          className={cn(
            'text-(--color-accent) transition-[stroke-dashoffset] duration-500 ease-out',
            progressClassName,
          )}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          stroke="currentColor"
          fill="transparent"
          r={radius}
          cx={size / 2}
          cy={size / 2}
          style={{
            transitionProperty: 'stroke-dashoffset',
            filter: 'drop-shadow(0 0 2px currentColor)',
          }}
        />
        {showLabel && (
          <text
            x={size / 2}
            y={size / 2}
            transform={`rotate(90, ${size / 2}, ${size / 2})`}
            textAnchor="middle"
            dominantBaseline="central"
            className={cn('select-none fill-foreground font-medium tabular-nums', valueClassName)}
            style={{ fontSize: size * 0.28 }}
          >
            {Math.round(safeProgress)}
          </text>
        )}
      </svg>
    )
  },
)

'use client'

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

// Global user interaction listener to unlock AudioContext immediately on first gesture
if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

/**
 * Plays a soft, tactile micro-click sound for hover interactions.
 */
export function playHoverSound(volume = 0.12, pitch = 1.2) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {
    // Ignore audio initialization edge cases
  }
}

/**
 * Plays a crisp tactile click sound for click actions and selections.
 */
export function playClickSound(volume = 0.2, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {
    // Ignore audio initialization edge cases
  }
}

/**
 * Plays a subtle micro-tick sound for slider/fader dragging or value ticks.
 */
export function playTickSound(volume = 0.1, pitch = 1.5) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {
    // Ignore audio initialization edge cases
  }
}

/**
 * Plays a rich, clear "bouncing ball" boing/pop sound for bounce navigation.
 */
export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    // Main oscillator for the bouncy pitch contour (boing / pop)
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    // Sub-pop oscillator for punchy ball impact body
    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {
    // Ignore audio initialization edge cases
  }
}
